import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.CyZTVJbV.js";const g=JSON.parse('{"title":"🌱 kiwa v1.13 — Realtime 縦軸 + perf harness (@kiwa-test/realtime v0.1 + @kiwa-test/perf-harness v0.1 + dogfood 3 app + docs 3 pillars + gh-pages 更新、 7 sub 全 resolved)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.13/gh-discussions-announcement.md","filePath":"announcements/v1.13/gh-discussions-announcement.md"}'),o={name:"announcements/v1.13/gh-discussions-announcement.md"};function r(n,e,c,d,l,h){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="🌱-kiwa-v1-13-—-realtime-縦軸-perf-harness-kiwa-test-realtime-v0-1-kiwa-test-perf-harness-v0-1-dogfood-3-app-docs-3-pillars-gh-pages-更新、-7-sub-全-resolved" tabindex="-1">🌱 kiwa v1.13 — Realtime 縦軸 + perf harness (<code>@kiwa-test/realtime</code> v0.1 + <code>@kiwa-test/perf-harness</code> v0.1 + dogfood 3 app + docs 3 pillars + gh-pages 更新、 7 sub 全 resolved) <a class="header-anchor" href="#🌱-kiwa-v1-13-—-realtime-縦軸-perf-harness-kiwa-test-realtime-v0-1-kiwa-test-perf-harness-v0-1-dogfood-3-app-docs-3-pillars-gh-pages-更新、-7-sub-全-resolved" aria-label="Permalink to &quot;🌱 kiwa v1.13 — Realtime 縦軸 + perf harness (`@kiwa-test/realtime` v0.1 + `@kiwa-test/perf-harness` v0.1 + dogfood 3 app + docs 3 pillars + gh-pages 更新、 7 sub 全 resolved)&quot;">​</a></h1><p>The v1.13 milestone (<strong>7/7 GitHub Issues resolved</strong>) just landed. v1.11 established the release-gate SSOT. v1.12 extended it to non-determinism (AI-LLM cost / latency / token / accuracy). v1.13 absorbs the <strong>second axis of non-triviality — time</strong>. Realtime providers push events over time; clients may be offline while pushes keep coming; order matters; buffers overflow. v1.13 lands a unified mock harness across Supabase Realtime + Ably + Pusher + Socket.io / SSE, wires 3 dogfood apps around it, and introduces <code>docs/concepts/realtime-testing.md</code> as the time-axis SSOT.</p><h2 id="_1-kiwa-test-perf-harness-v0-1-—-5-target-generic-perf-harness-v1-13-1" tabindex="-1">1. <code>@kiwa-test/perf-harness</code> v0.1 — 5 target generic perf harness (v1.13-1) <a class="header-anchor" href="#_1-kiwa-test-perf-harness-v0-1-—-5-target-generic-perf-harness-v1-13-1" aria-label="Permalink to &quot;1. `@kiwa-test/perf-harness` v0.1 — 5 target generic perf harness (v1.13-1)&quot;">​</a></h2><p>Feeds the 11-axis release gate&#39;s <code>perf.p95Ms</code> axis with p50 / p95 / p99 measurements + regression detection + baseline persistence + <code>/kiwa-perf</code> skill. 5 targets — <code>bench.request</code> / <code>bench.function</code> / <code>bench.stream</code> / <code>bench.batch</code> / <code>bench.worker</code>.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { bench, evaluateBaseline } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@kiwa-test/perf-harness&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> result</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> bench.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">function</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  name: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;add-1&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  fn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  iterations: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10_000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">console.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(result); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// { p50: 0.02, p95: 0.05, p99: 0.11 }</span></span></code></pre></div><h2 id="_2-kiwa-test-realtime-v0-1-—-4-provider-統一-mock-v1-13-2" tabindex="-1">2. <code>@kiwa-test/realtime</code> v0.1 — 4 provider 統一 mock (v1.13-2) <a class="header-anchor" href="#_2-kiwa-test-realtime-v0-1-—-4-provider-統一-mock-v1-13-2" aria-label="Permalink to &quot;2. `@kiwa-test/realtime` v0.1 — 4 provider 統一 mock (v1.13-2)&quot;">​</a></h2><p>One engine, 4 SDK adapters. All 5 realtime semantics covered — <strong>presence</strong> / <strong>broadcast</strong> / <strong>postgres_changes</strong> / <strong>room</strong> / <strong>reconnect</strong>.</p><ul><li><strong><code>createSupabaseRealtimeMock</code></strong> — <code>channel.on(&#39;presence&#39; | &#39;broadcast&#39; | &#39;postgres_changes&#39;, filter, handler)</code> + <code>channel.track / untrack / send</code></li><li><strong><code>createAblyMock</code></strong> — <code>channels.get / subscribe / presence.subscribe / history rewind</code></li><li><strong><code>createPusherMock</code></strong> — <code>subscribeChannel / bind / trigger</code> + <code>presence-*</code> channel members</li><li><strong><code>createSocketioMock</code></strong> — <code>io(namespace).join(room).emit / on</code> + <code>io.of(namespace).to(room).emit</code></li></ul><p>The 4 adapters sit on top of one engine (<code>packages/realtime/src/engine.ts</code>) that owns a <strong>discrete + synchronous virtual timeline</strong> — subscribe, and events fire on a per-channel <code>delay</code> schedule you declared upfront. Because there is no real socket, tests can assert on the exact number of events delivered per channel, the exact ordering across channels, the exact drop count from backpressure, and the exact number of reconnect attempts — signals that real sockets under jitter never surface cleanly.</p><h2 id="_3-dogfood-app-3-種-—-real-vs-mock-chat-cursor-notification-v1-13-3-4-5" tabindex="-1">3. Dogfood app 3 種 — real vs mock, chat / cursor / notification (v1.13-3 / -4 / -5) <a class="header-anchor" href="#_3-dogfood-app-3-種-—-real-vs-mock-chat-cursor-notification-v1-13-3-4-5" aria-label="Permalink to &quot;3. Dogfood app 3 種 — real vs mock, chat / cursor / notification (v1.13-3 / -4 / -5)&quot;">​</a></h2><p>Every realtime use-case pattern gets an example app that runs against <strong>both the real provider and the kiwa mock</strong>. Trace differences feed the fidelity axis of the 7-axis common branch (realtime providers do <strong>not</strong> activate the AI-LLM 11-axis branch — the <code>provider</code> prefix <code>@kiwa-test/realtime</code> does not match <code>@kiwa-test/ai-</code>).</p><ul><li><strong><code>examples/dogfood-supabase-realtime-chat/</code></strong> (v1.13-3) — Supabase Realtime chat + presence + typing indicator + 500 ms typing debounce</li><li><strong><code>examples/dogfood-ably-collab-cursor/</code></strong> (v1.13-4) — Ably shared cursor + 60 fps client-side throttle + history rewind for late joiners</li><li><strong><code>examples/dogfood-socketio-notification/</code></strong> (v1.13-5) — Socket.io / SSE per-room push + reconnect + pending replay + bounded backpressure queue (drop counts observable)</li></ul><p>All three follow the same <strong>provider-neutral adapter interface + <code>KIWA_MODE=real|mock</code> split + trace-diffing fidelity harness</strong> template that v1.11 established and v1.12 confirmed.</p><p>Real-world release-gate discovery — running the Supabase Realtime dogfood without <code>SUPABASE_URL</code> + <code>SUPABASE_ANON_KEY</code> correctly records 4 divergences (<code>joinRoom</code> / <code>sendMessage</code> / <code>getPresence</code> / <code>sendTyping</code>) as <code>BEHAVIORAL_DIVERGENCE</code>, so the mock is not spuriously credited with parity it cannot demonstrate. The gate stays honest even in local dev.</p><h2 id="_4-docs-補強-—-tutorials-migration-concept-doc-v1-13-6" tabindex="-1">4. Docs 補強 — tutorials + migration + concept doc (v1.13-6) <a class="header-anchor" href="#_4-docs-補強-—-tutorials-migration-concept-doc-v1-13-6" aria-label="Permalink to &quot;4. Docs 補強 — tutorials + migration + concept doc (v1.13-6)&quot;">​</a></h2><ul><li><strong><a href="https://github.com/cardene777/kiwa/blob/main/docs/tutorials/09-supabase-realtime-chat.md" target="_blank" rel="noreferrer"><code>docs/tutorials/09-supabase-realtime-chat.md</code></a></strong> — Supabase Realtime chat + presence + 500 ms typing debounce</li><li><strong><a href="https://github.com/cardene777/kiwa/blob/main/docs/tutorials/10-ably-collab-cursor.md" target="_blank" rel="noreferrer"><code>docs/tutorials/10-ably-collab-cursor.md</code></a></strong> — Ably shared cursor + 60 fps throttle + history rewind</li><li><strong><a href="https://github.com/cardene777/kiwa/blob/main/docs/tutorials/11-socketio-notification.md" target="_blank" rel="noreferrer"><code>docs/tutorials/11-socketio-notification.md</code></a></strong> — Socket.io notification + reconnect + pending replay + backpressure</li><li><strong><a href="https://github.com/cardene777/kiwa/blob/main/docs/migrations/v1.12-to-v1.13.md" target="_blank" rel="noreferrer"><code>docs/migrations/v1.12-to-v1.13.md</code></a></strong> — additive-only migration, no release-gate axis change</li><li><strong><a href="https://github.com/cardene777/kiwa/blob/main/docs/concepts/realtime-testing.md" target="_blank" rel="noreferrer"><code>docs/concepts/realtime-testing.md</code></a></strong> — time-axis mock SSOT (why v1.11 + v1.12 scalar axes are not enough for sequences, how 5 realtime axes translate into fidelity + perf, why the mock timeline is discrete + synchronous on purpose)</li></ul><h2 id="_5-vitepress-github-pages-—-sidebar-update-no-skeleton-change-v1-13-7" tabindex="-1">5. VitePress + GitHub Pages — sidebar update, no skeleton change (v1.13-7) <a class="header-anchor" href="#_5-vitepress-github-pages-—-sidebar-update-no-skeleton-change-v1-13-7" aria-label="Permalink to &quot;5. VitePress + GitHub Pages — sidebar update, no skeleton change (v1.13-7)&quot;">​</a></h2><p>The v1.11-6 VitePress skeleton is reused unchanged. <code>docs/.vitepress/config.mts</code> gains sidebar entries for the 3 new tutorials, the concept doc, and the v1.12→v1.13 migration. <code>/docs-publish-kiwa</code> runs <code>pnpm docs:build</code> → <code>git worktree add ../kiwa-gh-pages gh-pages</code> → dist copy → push, refreshing <code>https://cardene777.github.io/kiwa/</code> without touching CI. Playwright docs E2E gains 5 new specs (tutorial 09/10/11 + concept + migration v1.12→v1.13) alongside the existing v1.11 + v1.12 spec, and a new <code>pnpm test:docs-e2e</code> script wires them into one command.</p><h2 id="migration" tabindex="-1">Migration <a class="header-anchor" href="#migration" aria-label="Permalink to &quot;Migration&quot;">​</a></h2><p>v1.12 users can adopt v1.13 without touching existing tests. Add the new packages when you want to test realtime or measure perf:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa-test/realtime</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @kiwa-test/perf-harness</span></span></code></pre></div><p>The release gate does not gain new axes in v1.13 — realtime providers land on the 7-axis common branch. The <code>provider</code> prefix <code>@kiwa-test/realtime</code> does <strong>not</strong> match <code>@kiwa-test/ai-</code>, so the 11-axis branch stays exclusive to AI-LLM providers.</p><p>Full migration guide: <a href="https://github.com/cardene777/kiwa/blob/main/docs/migrations/v1.12-to-v1.13.md" target="_blank" rel="noreferrer">v1.12 → v1.13</a>.</p><p>Sub-Issue AC verification: <a href="https://github.com/cardene777/kiwa/issues/709" target="_blank" rel="noreferrer">#709</a> (parent) → <a href="https://github.com/cardene777/kiwa/issues/707" target="_blank" rel="noreferrer">#707</a> <a href="https://github.com/cardene777/kiwa/issues/710" target="_blank" rel="noreferrer">#710</a> <a href="https://github.com/cardene777/kiwa/issues/711" target="_blank" rel="noreferrer">#711</a> <a href="https://github.com/cardene777/kiwa/issues/712" target="_blank" rel="noreferrer">#712</a> <a href="https://github.com/cardene777/kiwa/issues/713" target="_blank" rel="noreferrer">#713</a> <a href="https://github.com/cardene777/kiwa/issues/714" target="_blank" rel="noreferrer">#714</a> <a href="https://github.com/cardene777/kiwa/issues/715" target="_blank" rel="noreferrer">#715</a>.</p><h2 id="v1-14-candidates" tabindex="-1">v1.14+ candidates <a class="header-anchor" href="#v1-14-candidates" aria-label="Permalink to &quot;v1.14+ candidates&quot;">​</a></h2><p>v1.11 milestone parent (#680) で列挙した v1.12+ 候補のうち v1.12 / v1.13 で採用しなかったもの + v1.12 announcement で追加した AI-LLM 深化候補。</p><ul><li>Storybook integration (component test 隙間、 v2.0 pull-forward 候補)</li><li>Dragonfly (2025 新興 Redis 互換 cache、 eco system 熟成待ち)</li><li>Reth (Rust Ethereum execution client、 dApp test 需要が育つ)</li><li>Go Iris + Chi (framework 縦深化続き)</li><li>Payment 系 (Stripe / Paddle / Lemon Squeezy webhook mock)</li><li>Search 系 (Meilisearch / Algolia / Typesense)</li><li>Observability 深堀り (OpenTelemetry / Datadog / Sentry)</li><li>AI-LLM 深化 (multimodal vision / audio + MCP tool + agent orchestration)</li></ul><p>Happy testing! 🌱</p>',28)])])}const k=s(o,[["render",r]]);export{g as __pageData,k as default};
